window.docContents[190].resolve({"/#programs-proofs-summary":{"contents":"\n\n\n\n\n\n\n\n\n\n\n\n","context":"Functional Programming in Lean\u0009Programming, Proving, and Performance","header":"8.8. Summary","id":"/#programs-proofs-summary"},"/#standard-classes":{"contents":"This section presents a variety of operators and functions that can be overloaded using type classes in Lean.\nEach operator or function corresponds to a method of a type class.\nUnlike C++, infix operators in Lean are defined as abbreviations for named functions; this means that overloading them for new types is not done using the operator itself, but rather using the underlying name (such as ).\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n","context":"Functional Programming in Lean\u0009Overloading and Type Classes","header":"3.5. Standard Classes","id":"/#standard-classes"}});